import React, { useState } from 'react';
import axios from 'axios';
import { Chat } from './Chat';
import { ResumePreview } from './ResumePreview';
import { LoadingSpinner } from './ui/LoadingSpinner';

export function ResumeBuilder() {
  const [resumeData, setResumeData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  
  // Your form data, assuming it's all filled correctly.
  const name = 'John Doe'; // For example, your form state can be pulled from here
  const email = 'john@example.com';
  const experience = '5 years of experience in software development';
  const education = 'BSc in Computer Science';
  const skills = 'React, Node.js, Python';

  // Handle generating the resume
  const generateResume = async () => {
    if (!name || !email || !experience || !education || !skills) {
      alert('Please fill in all the fields.');
      return;
    }

    setIsLoading(true);

    try {
      const response = await axios.post('http://127.0.0.1:5000/api/generate-resume', {
        conversationHistory: [
          { question: 'What is your name?', response: name },
          { question: 'What is your email?', response: email },
          { question: 'Describe your work experience.', response: experience },
          { question: 'Describe your educational background.', response: education },
          { question: 'What are your skills?', response: skills }
        ]
      });

      console.log("Generated Resume Data:", response.data);  // Log the API response
      setResumeData(response.data); // Update the state with the generated resume data
    } catch (error) {
      console.error('Error generating resume:', error);
      setError('An error occurred while generating the resume. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <div className="bg-white rounded-lg shadow">
        <Chat />
      </div>
      <div className="bg-white rounded-lg shadow">
        {isLoading ? (
          <LoadingSpinner />
        ) : (
          <>
            {resumeData ? (
              <ResumePreview resumeData={resumeData} />
            ) : (
              <button 
                onClick={generateResume} 
                className="px-4 py-2 bg-blue-500 text-white rounded"
              >
                Generate Resume
              </button>
            )}
            {error && <div className="text-red-500">{error}</div>}
          </>
        )}
      </div>
    </div>
  );
}
